<template>
  <Teleport to="body">
    <DocumentFileDrop :enabled="tab==='source'&&!preview&&!busy" :ignore-dialogs="false" @file="dropFile" @error="error=$event" />
    <div class="document-import-overlay" @click.self="close" @keydown.esc.stop.prevent="close">
      <section class="document-import-dialog" role="dialog" aria-modal="true" aria-label="导入小说或剧本">
        <header><div><small>DOCUMENT IMPORT</small><h2>导入小说／剧本</h2><p>保留原文件，先检查分段，再导入本项目。</p></div><button type="button" class="btn btn-icon" aria-label="关闭" :disabled="committing" @click="close">×</button></header>
        <nav class="import-tabs"><button type="button" :class="{on:tab==='source'}" @click="tab='source'">{{ preview ? '分段预览' : '选择原文' }}</button><button type="button" :class="{on:tab==='history'}" @click="openHistory">导入记录 <span>{{ history.length || '' }}</span></button></nav>
        <div v-if="tab==='history'" class="import-history">
          <p class="import-hint">原文件保存在项目的私有资料中，只有有权限的账户能够下载。最多显示最近 50 次。</p>
          <p v-if="!history.length" class="import-empty">还没有导入记录。</p>
          <article v-for="row in history" :key="row.id"><div><strong>{{ row.filename }}</strong><small>{{ row.kind==='script'?'已完成剧本':'小说原文' }} · {{ row.encoding }} · {{ Number(row.source_characters).toLocaleString() }} 字符 · {{ formatDate(row.created_at) }}</small></div><span :class="['import-state',{done:row.committed_at}]">{{ row.committed_at?'已导入':'已预览' }}</span><a class="btn btn-sm" :href="`/api/v1/dramas/${dramaId}/imports/${row.id}/source`" download>下载原文件</a></article>
        </div>
        <div v-else-if="!preview" class="import-source-body">
          <div class="import-kind"><button type="button" :class="{on:kind==='novel'}" @click="kind='novel'"><b>小说原文</b><span>按“章／回”拆分，之后可进入 AI 改写。</span></button><button type="button" :class="{on:kind==='script'}" @click="kind='script'"><b>已完成剧本</b><span>按“集／话”拆分，直接作为剧本使用。</span></button></div>
          <div class="import-file-row"><label class="import-file-button"><input ref="fileInput" type="file" accept=".txt,.md,text/plain,text/markdown" :disabled="busy" @change="pickFile" /><span>{{ reading?'正在读取…':fileName || '选择或拖入 TXT／MD 文件' }}</span></label><span>可拖入窗口，或在下面粘贴正文</span><label v-if="fileBytes">编码 <select v-model="encoding"><option value="auto">自动识别</option><option value="utf-8">UTF-8</option><option value="utf-16le">UTF-16 LE</option><option value="utf-16be">UTF-16 BE</option><option value="gb18030">GB18030／GBK</option></select></label><button v-if="fileBytes" type="button" class="btn btn-sm" @click="clearFile">清除文件</button></div>
          <textarea v-model="pasted" :disabled="!!fileBytes || busy" placeholder="粘贴完整正文。标题、对白、备注都会保留，不自动删除或改写。" class="import-paste" />
          <p class="import-hint">最大 6 MB，最多 1,000 段。小说识别“第一章／第1章”；剧本识别“第一集／第1集”。场景里的“第一幕”“1-01”不会拆成新的一集。</p>
        </div>
        <div v-else class="import-preview-body">
          <div class="import-preview-summary"><div><strong>{{ preview.filename }}</strong><span>{{ kind==='script'?'已完成剧本':'小说原文' }} · {{ preview.encoding }} · 原文 {{ preview.source_characters.toLocaleString() }} 字符</span></div><b>{{ sections.length }} 段</b><button type="button" class="btn btn-sm" :disabled="busy" @click="backToSource">重新选择</button></div>
          <div v-if="preview.warnings?.length" class="import-warning"><p v-for="note in preview.warnings" :key="note">{{ note }}</p></div>
          <div v-if="preview.previous_imports?.length" class="import-warning"><p>这份原文已经导入过 {{ preview.previous_imports.length }} 次，请先核对导入记录。</p><label><input v-model="allowDuplicateSource" type="checkbox" />我确认重复使用这份原文，新建一批剧集</label></div>
          <div class="import-editor-layout">
            <aside class="import-section-list" aria-label="分段列表"><button v-for="(part,index) in sections" :key="part.local_key" type="button" :class="{on:index===active}" @click="active=index"><b>第 {{ part.episode_number }} 集</b><span>{{ part.title }}</span><small>{{ part.content.length.toLocaleString() }} 字符 <em v-if="part.content.length>200000">需拆分</em></small></button></aside>
            <div v-if="current" class="import-section-editor">
              <div class="import-title-row"><label>目标集号<input v-model.number="current.episode_number" type="number" min="1" max="1000000" /></label><label>剧集标题<input v-model="current.title" maxlength="200" /></label></div>
              <p class="import-source-label">原文{{ kind==='novel'?'章节':'集数' }}：{{ current.source_title || '未标注' }}<span>序号 {{ current.source_number ?? '—' }}</span></p>
              <textarea ref="editor" v-model="current.content" spellcheck="false" aria-label="完整分段正文" />
              <div class="import-edit-tools"><span>{{ current.content.length.toLocaleString() }} 字符</span><button type="button" class="btn btn-sm" @click="splitAtCursor">在光标处拆分</button><button type="button" class="btn btn-sm" :disabled="active>=sections.length-1" @click="mergeNext">与下一段合并</button><button type="button" class="btn btn-sm" @click="renumber">从首段集号重新顺排</button></div>
            </div>
          </div>
          <details class="import-models"><summary>导入后使用的图片／视频模型（可稍后配置）</summary><div><label>图片模型<select v-model.number="imageConfigId"><option :value="0">稍后配置</option><option v-for="config in imageConfigs" :key="config.id" :value="config.id">{{ config.display_name || config.name || config.model }}</option></select></label><label>视频模型<select v-model.number="videoConfigId"><option :value="0">稍后配置</option><option v-for="config in videoConfigs" :key="config.id" :value="config.id">{{ config.display_name || config.name || config.model }}</option></select></label><label>分辨率<select v-model="resolution"><option v-for="value in resolutionOptions" :key="value" :value="value">{{ value }}</option></select></label></div></details>
        </div>
        <p v-if="error" class="import-error" role="alert">{{ error }}</p>
        <footer><span>{{ preview ? (kind==='script'?'导入后可直接提取资产；不会自动调用模型。':'导入后从原始内容开始；不会自动改写或生成。') : '只整理和保存文件，不消耗模型额度。' }}</span><div><button type="button" class="btn" :disabled="committing" @click="close">取消</button><button v-if="tab==='source'&&!preview" type="button" class="btn btn-primary" :disabled="busy||(!fileBytes&&!pasted.trim())" @click="prepare">{{ busy?'正在识别…':'识别并预览' }}</button><button v-else-if="tab==='source'" type="button" class="btn btn-primary" :disabled="busy||!sections.length" @click="commit">{{ committing?'正在导入…':`确认导入 ${sections.length} 集` }}</button></div></footer>
      </section>
    </div>
  </Teleport>
</template>
<script setup>
import { computed, ref, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { api, aiConfigAPI } from '~/composables/useApi'
import DocumentFileDrop from '~/components/DocumentFileDrop.vue'
import {documentFileError} from '~/utils/document-file.js'
const props=defineProps({dramaId:{type:Number,required:true},initialFile:{type:Object,default:null}}),emit=defineEmits(['close','imported'])
const tab=ref('source'),kind=ref('script'),pasted=ref(''),fileName=ref(''),fileBytes=ref(''),encoding=ref('auto'),reading=ref(false),loading=ref(false),committing=ref(false),error=ref(''),preview=ref(null),sections=ref([]),active=ref(0),editor=ref(null),fileInput=ref(null),history=ref([]),imageConfigs=ref([]),videoConfigs=ref([]),imageConfigId=ref(0),videoConfigId=ref(0),allowDuplicateSource=ref(false)
const busy=computed(()=>reading.value||loading.value||committing.value),current=computed(()=>sections.value[active.value]||null),resolution=ref('720p')
const videoConfig=computed(()=>videoConfigs.value.find(config=>Number(config.id)===Number(videoConfigId.value)))
const resolutionOptions=computed(()=>{const config=videoConfig.value,declared=config?.capabilities?.resolutions||config?.parameters?.find(parameter=>parameter.key==='resolution'||parameter.binding==='resolution')?.options;return Array.isArray(declared)&&declared.length?declared.map(value=>String(value&&typeof value==='object'?value.value:value)):['720p','480p','1080p']})
watch(videoConfig,config=>{const preferred=config?.defaults?.resolution;resolution.value=resolutionOptions.value.includes(preferred)?preferred:resolutionOptions.value.includes('720p')?'720p':resolutionOptions.value[0]},{flush:'sync'})
let revision=0,disposed=false,commitPacket=null
const formatDate=value=>new Date(value).toLocaleString('zh-CN',{hour12:false})
const sectionKey=()=>globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random()
function close(){if(committing.value)return;disposed=true;revision++;emit('close')}
function clearFile(){revision++;reading.value=false;fileBytes.value='';fileName.value='';if(fileInput.value)fileInput.value.value='';error.value=''}
async function pickFile(event){const file=event.target.files?.[0];if(file)await readFile(file)}
async function readFile(file){if(disposed||loading.value||committing.value)return;const invalid=documentFileError(file);if(invalid){error.value=invalid;return}const token=++revision;error.value='';reading.value=true;try{const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length>6*1024*1024)throw Error('文件过大');let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));if(disposed||token!==revision)return;fileBytes.value=btoa(binary);fileName.value=file.name;encoding.value='auto'}catch{if(token===revision)error.value='文件读取失败，请重新选择。'}finally{if(token===revision)reading.value=false}}
function dropFile(file){if(busy.value||preview.value)return;if((fileBytes.value||pasted.value.trim())&&!window.confirm('替换当前选中的文件或粘贴内容？尚未确认导入的内容不会写入剧集。'))return;void readFile(file)}
watch(()=>props.initialFile,file=>{if(file)void readFile(file)},{immediate:true})
async function prepare(){if(busy.value)return;const token=++revision;loading.value=true;error.value='';try{const value=await api.post(`/dramas/${props.dramaId}/imports/preview`,{kind:kind.value,filename:fileBytes.value?fileName.value:'粘贴文本.txt',...(fileBytes.value?{file_base64:fileBytes.value,encoding:encoding.value}:{text:pasted.value})});if(disposed||token!==revision)return;preview.value=value;sections.value=value.sections.map(part=>({...part,local_key:sectionKey()}));active.value=0;imageConfigId.value=value.model_defaults?.image_config_id||0;videoConfigId.value=value.model_defaults?.video_config_id||0;allowDuplicateSource.value=false;commitPacket=null}catch(failure){if(token===revision)error.value=failure.message||'预览失败。'}finally{if(token===revision)loading.value=false}}
function backToSource(){preview.value=null;sections.value=[];commitPacket=null;error.value=''}
function renumber(){const start=Number(sections.value[0]?.episode_number)||1;sections.value.forEach((part,index)=>{part.episode_number=start+index});commitPacket=null}
async function splitAtCursor(){const part=current.value,pos=editor.value?.selectionStart;if(!part||!pos||pos>=part.content.length){error.value='请先将光标放在正文中间，再点击拆分。';return}if(/[\uD800-\uDBFF]/u.test(part.content[pos-1])&&/[\uDC00-\uDFFF]/u.test(part.content[pos])){error.value='请在完整字符之间拆分。';return}const second={...part,title:part.title+'（续）',content:part.content.slice(pos),source_start:Math.min(part.source_end,part.source_start+pos),local_key:sectionKey()};part.content=part.content.slice(0,pos);part.source_end=second.source_start;sections.value.splice(active.value+1,0,second);renumber();error.value='';await nextTick()}
function mergeNext(){const part=current.value,next=sections.value[active.value+1];if(!part||!next)return;part.content+=next.content;part.source_end=next.source_end;sections.value.splice(active.value+1,1);renumber();error.value=''}
async function openHistory(){tab.value='history';try{history.value=await api.get(`/dramas/${props.dramaId}/imports`)}catch(failure){error.value=failure.message}}
async function commit(){if(busy.value)return;error.value='';if(preview.value.previous_imports?.length&&!allowDuplicateSource.value){error.value='请核对导入记录，确需重复导入时勾选确认。';return}const snapshot={sections:sections.value.map(({local_key,...part})=>part),image_config_id:imageConfigId.value||null,video_config_id:videoConfigId.value||null,resolution:resolution.value,allow_duplicate_source:allowDuplicateSource.value};const duplicate=new Set();for(const [index,part] of snapshot.sections.entries()){if(!part.title.trim()||!part.content.trim()){error.value=`第 ${index+1} 段的标题或正文为空。`;return}if(part.content.length>200000){active.value=index;error.value='这段超过 200,000 字符，请在光标处拆分后再导入。';return}if(!Number.isSafeInteger(part.episode_number)||part.episode_number<1||duplicate.has(part.episode_number)){error.value='目标集号需要为正整数，且不能重复。';return}duplicate.add(part.episode_number)}commitPacket=JSON.stringify(snapshot);committing.value=true;try{const receipt=await api.post(`/dramas/${props.dramaId}/imports/${preview.value.id}/commit`,JSON.parse(commitPacket));if(!disposed)emit('imported',receipt)}catch(failure){if(!disposed)error.value=failure.message||'导入结果未确认，保留当前预览后可重试；服务器会校验重复提交。'}finally{committing.value=false}}
onMounted(async()=>{try{const [images,videos]=await Promise.all([aiConfigAPI.list('image'),aiConfigAPI.list('video')]);if(!disposed){imageConfigs.value=images||[];videoConfigs.value=videos||[]}}catch{/* Content can be imported before model configuration. */}})
onBeforeUnmount(()=>{disposed=true;revision++})
</script>
<style scoped>
