.import-file-button{border:1px dashed var(--border);border-radius:8px;padding:11px 18px;cursor:pointer;color:var(--text-1);max-width:50%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.import-file-button input{display:none}.document-import-dialog select,.document-import-dialog input{border:1px solid var(--border);background:var(--bg-1);color:var(--text-1);border-radius:7px;padding:8px 10px;font-size:11px;min-width:0}.import-paste{width:100%;height:260px;resize:vertical;border:1px solid var(--border);border-radius:10px;padding:16px;font-size:12px;line-height:1.9;color:var(--text-1);background:var(--bg-2,#fafbfc)}.import-paste:disabled{opacity:.5}.import-hint{margin-top:10px}.import-preview-body{padding:18px 26px;min-height:0;overflow:auto}.import-preview-summary{display:flex;gap:16px;align-items:center;margin-bottom:12px}.import-preview-summary>div{display:grid;gap:5px;min-width:0;flex:1}.import-preview-summary strong{font-size:12px;overflow-wrap:anywhere}.import-preview-summary span{font-size:10px;color:var(--text-3)}.import-preview-summary>b{font-size:12px;color:var(--accent-text)}.import-warning{padding:10px 13px;font-size:11px;line-height:1.8;background:#fff7e9;color:#9b691d;border:1px solid #f6e0b6;border-radius:9px;margin-bottom:12px}.import-warning p{margin:0}.import-editor-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:18px;height:390px;min-height:260px}.import-section-list{overflow:auto;border:1px solid var(--border);border-radius:10px;background:var(--bg-2,#fafbfc)}.import-section-list button{display:grid;gap:6px;width:100%;text-align:left;padding:12px 14px;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--text-1);cursor:pointer}.import-section-list button.on{background:var(--accent-bg,#fff3e9);box-shadow:inset 3px 0 var(--accent,#ff7a20)}.import-section-list b{font-size:10px}.import-section-list span{font-size:11px;overflow-wrap:anywhere}.import-section-list small{font-size:9px;color:var(--text-3)}.import-section-list em{font-style:normal;color:var(--error,#d95050);margin-left:5px}.import-section-editor{display:flex;min-width:0;min-height:0;flex-direction:column}.import-title-row{display:flex;gap:12px}.import-title-row label{display:grid;gap:7px;font-size:10px}.import-title-row label:first-child{width:95px;flex-shrink:0}.import-title-row label:last-child{flex:1}.import-source-label{font-size:10px;color:var(--text-3);margin:10px 0;overflow-wrap:anywhere}.import-source-label span{margin-left:10px}.import-section-editor textarea{width:100%;flex:1;min-height:100px;resize:none;padding:13px;border:1px solid var(--border);border-radius:9px;font-size:12px;line-height:1.9;color:var(--text-1);background:var(--bg-1)}.import-edit-tools{display:flex;gap:6px;align-items:center;padding-top:10px;flex-wrap:wrap}.import-edit-tools>span{font-size:10px;flex:1;color:var(--text-3)}.import-models{margin-top:15px;font-size:10px;color:var(--text-3)}.import-models summary{cursor:pointer}.import-models>div{display:flex;gap:16px;margin-top:12px}.import-models label{display:grid;gap:7px;flex:1}.document-import-dialog footer{border-top:1px solid var(--border)}.document-import-dialog footer>span{font-size:10px;line-height:1.8;color:var(--text-3)}.document-import-dialog footer>div{display:flex;gap:8px;flex-shrink:0}.import-error{font-size:11px;line-height:1.8;white-space:pre-wrap;padding:12px 26px;color:var(--error,#d74e4e);background:var(--error-bg,#fff1f1);flex-shrink:0}.import-history{padding:18px 26px;overflow:auto;min-height:300px}.import-history article{display:flex;align-items:center;gap:15px;padding:17px 0;border-bottom:1px solid var(--border)}.import-history article>div{flex:1;min-width:0;display:grid;gap:7px}.import-history strong{font-size:12px;overflow-wrap:anywhere}.import-history small{font-size:10px;color:var(--text-3)}.import-state{font-size:10px;padding:4px 8px;border-radius:12px;background:var(--bg-2);color:var(--text-3)}.import-state.done{background:#eaf8ef;color:#2686